1	import { Suspense } from "react";
2	import { headers } from "next/headers";
3	import { db } from "@/lib/db";
4	import { requireUser } from "@/lib/auth";
5	import { clientIp } from "@/lib/rate-limit";
6	import { hashIp } from "@/lib/coupon-order";
7	import { firstMonthFreeEligible, firstMonthFreeEnabled, firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
8	import { getSettingBool } from "@/lib/settings";
9	import { annualDiscountPct } from "@/lib/annual-discount";
10	import { extraDiskPerGbCents } from "@/lib/disk-expand";
11	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
12	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
13	import { VPS_TERMS, vpsTermPriceCents, termPriceCents, termDiscountPct } from "@/lib/billing-terms";
14	import { planIntroMonthlyCents } from "@/lib/intro-pricing";
15	import { regionsFrom, appSpriteKey, gameArt } from "@/lib/nx/catalog";
16	import { GAME_DISPLAY, GAME_GENRES, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "@/lib/games";
17	import { GAME_CONFIG_SCHEMAS } from "@/lib/game-config";
18	import { GAME_FAMILIES } from "@/lib/games";
19	import { stripeConfigured } from "@/lib/stripe";
20	import { paypalConfigured } from "@/lib/paypal";
21	import { coinbaseConfigured } from "@/lib/coinbase-commerce";
22	import { DeployView } from "@/components/nx/DeployView";
23	import type { AddonOption, EmailPlanOption, GameFamilyOption, HostingPlanOption, OsOption, PlanOption, TermOption } from "@/components/nx/order-types";
24	
25	/* Data for the VPS deploy wizard.
26	 *
27	 * The one rule this file exists to keep: every number the wizard can display is
28	 * computed HERE, by the same functions that charge the card, and handed down
29	 * already worked out. The view prints; it never multiplies.
30	 *
31	 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
32	 * rate plus a discount percent. Sending the percent would mean the browser does
33	 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
34	 * when the customer decides. Terms are few and plans are few, so the matrix is
35	 * cheap and it cannot drift from `vpsTermPriceCents`.
36	 */
37	
38	export const dynamic = "force-dynamic";
39	
40	/* Icon per image, keyed off the platform's own `family` value rather than
41	   sniffing the display name. Control panels and applications have families too
42	   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
43	const ICON_BY_FAMILY: Record<string, string> = {
44	  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
45	  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
46	  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
47	  mysql: "mysql", postgres: "postgres", redis: "redis",
48	  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
49	  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
50	};
51	function osIcon(family: string, category: string): string {
52	  return ICON_BY_FAMILY[family?.toLowerCase()]
53	    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
54	}
55	
56	/* The plan-card promo badge's percent — the REAL gap between the intro monthly
57	 * rate and the regular monthly rate, so "X% off" can never show a number a
58	 * plan doesn't actually carry. Computed here (once, server-side) rather than
59	 * in the card component, same discipline as every other price on this page:
60	 * the view prints, it does not work anything out. Null (no badge) unless
61	 * `introCents` is a genuine, positive discount off `regularCents`. */
62	function introBadgePercent(regularCents: number, introCents: number | null): number | null {
63	  if (introCents == null || regularCents <= 0 || introCents >= regularCents) return null;
64	  return Math.max(1, Math.min(99, Math.round((1 - introCents / regularCents) * 100)));
65	}
66	
67	export default async function NxDeployPage() {
68	  const user = await requireUser();
69	
70	  // Exit-intent 25%-off popup eligibility (Feature: EXIT25). "First-time
71	  // customer" is the codebase's own established predicate for exactly this
72	  // kind of gate — zero non-free `Server` rows — already enforced identically
73	  // by `firstTimeOnly` coupon checks in lib/order.ts and
74	  // lib/coupon-redemption.ts. Resolved HERE, server-side, and threaded down as
75	  // a plain boolean prop: the deploy page is already a server component
76	  // reading `user`, so there is no reason to let the client decide something
77	  // this consequential on its own.
78	  const [isFirstTimeCustomer, exitIntentEnabled] = await Promise.all([
79	    db.server.count({ where: { userId: user.id, isFree: false } }).then((n) => n === 0),
80	    getSettingBool("exit_intent_enabled", true),
81	  ]);
82	
83	  // Real, per-customer eligibility for the first-month-free hosting promo —
84	  // NOT a display detail, the exact same advisory pre-check
85	  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
86	  // wizard's hosting/email price was a flat, precomputed matrix with zero
87	  // per-user awareness (deliberately: "so there is no round-trip to make"),
88	  // which is why the promo's own plan-card badge ("First month free") and
89	  // the wizard's actual total disagreed — the matrix could not have known
90	  // whether THIS customer still qualifies. One extra check here, resolved
91	  // alongside the rest of this page's own data fetching.
92	  const hostingPromoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
93	  const hostingPromoEligible =
94	    firstMonthFreeAppliesTo("HOSTING") &&
95	    (await firstMonthFreeEnabled()) &&
96	    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));
97	
98	  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
99	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
100	    /* All three categories — the design's Server settings panel has a tab per
101	       category (Operating system / Control panels / Applications), which is
102	       exactly what ImageCategory already distinguishes. They are separated in
103	       the VIEW, not filtered out here: a game-server image is a real thing you
104	       can deploy, it just is not an answer to "pick an operating system". */
105	    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
106	       images, but Nxeon sells game servers as their own product with their own
107	       plans, panel and pricing — offering "Minecraft Server" as a VPS
108	       application sells the same thing twice, at the wrong price, without the
109	       game panel. Identified by `family` against the platform's own
110	       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
111	    db.osTemplate.findMany({
112	      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
113	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
114	    }),
115	    // enabled only — a disabled node is not a place we can provision.
116	    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
117	    // "from" prices for the service tiles — the cheapest live plan of each kind,
118	    // read from the same tables the order path prices against.
119	    // Every active tier: the wizard groups them into families itself, so one
120	    // query serves both the "from" price on the tiles and the tier picker.
121	    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
122	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
123	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
124	    annualDiscountPct(),
125	    extraDiskPerGbCents(),
126	    dedicatedIpMonthlyCents(),
127	    backupPlusMonthlyCents(),
128	  ]);
129	
130	  /* The monthly term is the reference rate the cards show by default; the wizard
131	     re-reads this matrix when the customer changes term. Priced through
132	     `vpsTermPriceCents`, the same helper `orderQuote` uses. */
133	  const priceMatrix: Record<string, Record<number, number>> = {};
134	  for (const p of plans) {
135	    priceMatrix[p.id] = {};
136	    for (const t of VPS_TERMS) {
137	      // term total / months = the effective monthly rate at that term
138	      priceMatrix[p.id][t.months] = Math.round(
139	        vpsTermPriceCents(p.priceCents, t.months, annualPct) / t.months
140	      );
141	    }
142	  }
143	
144	  /* "Recommended" is the middle of the ladder, not the most expensive — the
145	     default has to be a defensible choice, not an upsell. */
146	  const recommendedId = plans.length ? plans[Math.floor((plans.length - 1) / 2)].id : null;
147	
148	  const planOptions: PlanOption[] = plans.map((p) => ({
149	    id: p.id,
150	    slug: p.slug,
151	    name: p.name,
152	    cpuCores: p.cpuCores,
153	    ramMB: p.ramMB,
154	    diskGB: p.diskGB,
155	    bandwidthTB: p.bandwidthTB,
156	    monthlyCents: p.priceCents,
157	    effectiveMonthlyCents: priceMatrix[p.id][1],
158	    introMonthlyCents: p.introPriceCents ?? null,
159	    introRenewalMonthlyCents: p.introPriceCents ? p.priceCents : null,
160	    introPercent: introBadgePercent(p.priceCents, planIntroMonthlyCents(p)),
161	    recommended: p.id === recommendedId,
162	  }));
163	
164	  const osOptions: OsOption[] = oses.map((o) => ({
165	    id: o.id,
166	    name: o.name,
167	    version: o.version ?? "",
168	    icon: osIcon(o.family, o.category),
169	    category: o.category,
170	    family: o.family,
171	    spriteKey: o.category === "PLAIN_OS" ? null : appSpriteKey(o.name),
172	  }));
173	
174	  const termOptions: TermOption[] = VPS_TERMS.map((t) => ({
175	    months: t.months,
176	    label: t.label,
177	    discountPercent: termDiscountPct(t.months, annualPct),
178	  }));
179	
180	  /* Add-on rates come from the same functions the charge path reads. A rate
181	     hardcoded next to a checkbox is how a display price and a charged price
182	     drift apart. */
183	  /* Families are built from the tiers that actually exist. A family with no
184	     active plan is not offered — the alternative is a card that leads to an
185	     empty tier list. Variants and the subdomain requirement come from the
186	     platform's own family schema, not from a list kept here. */
187	  // Leads the game grid, in this order, each badged "Popular" — the owner's
188	  // pick, not a computed ranking (no real play-count/order-volume signal
189	  // exists yet to rank by). `projectzomboid`/`sdtd` are the actual family
190	  // keys behind "Project Zomboid" / "7 Days to Die" (lib/games.ts
191	  // GAME_FAMILIES) — the display names aren't the lookup keys.
192	  const POPULAR_GAME_ORDER = ["minecraft", "rust", "valheim", "palworld", "projectzomboid", "terraria"];
193	  const gameFamilies: GameFamilyOption[] = (() => {
194	    const byFamily = new Map<string, typeof gamePlans>();
195	    for (const gp of gamePlans) {
196	      const list = byFamily.get(gp.gameFamily) ?? [];
197	      list.push(gp);
198	      byFamily.set(gp.gameFamily, list);
199	    }
200	    return [...byFamily.entries()].map(([family, tiers]) => {
201	      const schema = GAME_CONFIG_SCHEMAS[family];
202	      return {
203	        family,
204	        name: GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family,
205	        art: gameArt(family),
206	        variants: schema?.variants ?? [],
207	        defaultVariant: schema?.defaultVariant ?? "",
208	        genres: GAME_GENRES[family as keyof typeof GAME_GENRES] ?? [],
209	        /* Same source of truth quoteGameOrder (lib/game-order.ts) charges
210	           through — a second, hand-maintained "just minecraft" check here
211	           silently left every other hostname-connect family (ARK, the
212	           Source-engine titles, Satisfactory, Conan, 7 Days to Die,
213	           Enshrouded, and more) without a "Play address" field to fill in,
214	           so their orders could reach the payment step with no subdomain
215	           and no way to price. */
216	        needsSubdomain: family === "minecraft" || family === "bedrock"
217	          || HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily),
218	        /* Same lesson as needsSubdomain right above: a family's checkout-time
219	           required fields were never surfaced to the wizard at all, so an
220	           order for Valheim, CS2, Dragonwilds, Sunkenland, DST or Mordhau
221	           could reach Payment priced against an empty config and fail there
222	           with no field to fix it.
223	           NOT filtered by `field.phase` — that axis means "does changing this
224	           LATER need a redeploy" (FieldPhase is "deploy" | "live"), which has
225	           nothing to do with whether checkout should ask for it. Every field
226	           rides along here; the wizard shows `required` ones inline and folds
227	           the rest under a collapsed "Advanced settings" disclosure, since
228	           they all carry sensible defaults and are just as editable from the
229	           dashboard's Settings tab after purchase. */
230	        checkoutFields: schema?.fields ?? [],
231	        // Lead with the intro rate where one exists, same as every other
232	        // "from $X" price on this page — a tier's regular priceCents is its
233	        // RENEWAL rate post-grandfather-program, not what a new order pays.
234	        fromCents: Math.min(...tiers.map((t) => planIntroMonthlyCents(t) ?? t.priceCents)),
235	        popular: POPULAR_GAME_ORDER.includes(family),
236	        tiers: tiers.map((t) => ({
237	          id: t.id,
238	          name: t.name,
239	          ramMB: t.ramMB,
240	          cpuCores: t.cpuCores,
241	          diskGB: t.diskGB,
242	          slots: t.slots ?? null,
243	          monthlyCents: t.priceCents,
244	          termMonths: t.termMonths,
245	          // Same GRANDFATHER PROGRAM columns as Plan (lib/game-order.ts already
246	          // reads them at charge time) — `planIntroMonthlyCents` is generic
247	          // over any `{priceCents}` row, so this is the identical helper VPS
248	          // uses, not a second formula.
249	          introMonthlyCents: planIntroMonthlyCents(t),
250	          introRenewalMonthlyCents: planIntroMonthlyCents(t) !== null ? t.priceCents : null,
251	          introPercent: introBadgePercent(t.priceCents, planIntroMonthlyCents(t)),
252	        })),
253	      };
254	    }).sort((a, b) => {
255	      const pa = POPULAR_GAME_ORDER.indexOf(a.family);
256	      const pb = POPULAR_GAME_ORDER.indexOf(b.family);
257	      if (pa !== -1 || pb !== -1) return (pa === -1 ? 999 : pa) - (pb === -1 ? 999 : pb);
258	      return a.name.localeCompare(b.name);
259	    });
260	  })();
261	
262	  const hostingOptions: HostingPlanOption[] = hostingPlans.map((h) => ({
263	    id: h.id, name: h.name, tagline: h.tagline,
264	    diskGB: h.diskGB, maxSites: h.maxSites, maxDatabases: h.maxDatabases,
265	    bandwidthTB: h.bandwidthTB, mailboxes: h.mailboxes,
266	    freeMigration: h.freeMigration, featured: h.featured,
267	    monthlyCents: h.priceCents,
268	  }));
269	
270	  const emailOptions: EmailPlanOption[] = emailPlans.map((e) => ({
271	    id: e.id, name: e.name, mailboxes: e.mailboxes,
272	    storageGB: e.storageGB, monthlyCents: e.priceCents, termMonths: e.termMonths,
273	  }));
274	
275	  /* Hosting and email price through `termPriceCents` — the same helper their
276	     own charge paths use (lib/actions-hosting.ts, lib/actions-email-hosting.ts).
277	     Built as a matrix for the same reason as the VPS one: sending a rate and a
278	     discount percent would put the multiply back in the browser. */
279	  const hostingMatrix: Record<string, Record<number, number>> = {};
280	  // The real term total — `termPriceCents` unrounded-and-redivided — for the
281	  // checkout math. hostingMatrix above rounds THIS down to a per-month rate
282	  // for display ("$X/mo" labels), which is a real, separate rounding step:
283	  // re-multiplying that rounded rate back up by the term (as the checkout
284	  // total once did) silently drifts a cent or two from what the charge path
285	  // (lib/actions-hosting.ts's hostingChargeCents, same termPriceCents call)
286	  // actually bills. One rounding, at the total, shared with the charge path.
287	  const hostingTotalMatrix: Record<string, Record<number, number>> = {};
288	  // One month of the plan's own rate, credited when this customer still
289	  // qualifies — same shape as the VPS quote's `regularPlanCents - plan.priceCents`
290	  // (lib/order.ts), just carried alongside the matrix instead of computed by
291	  // a server round-trip. 0 (no credit) once first_month_free is off, already
292	  // claimed on this account/IP, or the plan changes and this needs recomputing.
293	  const hostingFirstMonthFreeCents: Record<string, number> = {};
294	  for (const h of hostingPlans) {
295	    hostingMatrix[h.id] = {};
296	    hostingTotalMatrix[h.id] = {};
297	    for (const t of VPS_TERMS) {
298	      const totalCents = termPriceCents(h.priceCents, t.months, annualPct);
299	      hostingTotalMatrix[h.id][t.months] = totalCents;
300	      hostingMatrix[h.id][t.months] = Math.round(totalCents / t.months);
301	    }
302	    hostingFirstMonthFreeCents[h.id] = hostingPromoEligible ? h.priceCents : 0;
303	  }
304	  const emailMatrix: Record<string, Record<number, number>> = {};
305	  const emailTotalMatrix: Record<string, Record<number, number>> = {};
306	  for (const e of emailPlans) {
307	    emailMatrix[e.id] = {};
308	    emailTotalMatrix[e.id] = {};
309	    for (const t of VPS_TERMS) {
310	      const totalCents = termPriceCents(e.priceCents, t.months, annualPct);
311	      emailTotalMatrix[e.id][t.months] = totalCents;
312	      emailMatrix[e.id][t.months] = Math.round(totalCents / t.months);
313	    }
314	  }
315	
316	  const addonOptions: AddonOption[] = [
317	    { key: "backup", name: "Backup Plus", note: "Longer retention, more restore points", icon: "archive", monthlyCents: backupCents, free: false },
318	    { key: "ip", name: "Dedicated IP", note: "An address of your own", icon: "nodes", monthlyCents: ipCents, free: false },
319	    { key: "malware", name: "Malware scanning", note: "Scheduled scans and alerts", icon: "shieldcheck", monthlyCents: 0, free: true },
320	    { key: "docker", name: "Docker pre-installed", note: "Ready for containers on first boot", icon: "docker", monthlyCents: 0, free: true },
321	  ];
322	
323	  return (
324	    // OrderProvider (components/nx/order.tsx) reads a marketing Deploy button's
325	    // selection off the URL via `useSearchParams()` (see lib/deploy-intent.ts) —
326	    // Next.js requires a Suspense boundary around any client component that
327	    // calls it, same as the old wizard's DeployHub did (see
328	    // app/dashboard/deploy/legacy-page.tsx.bak).
329	    <Suspense fallback={<div className="h-64 animate-pulse rounded-3xl border border-white/[0.06] bg-navy-900/40" />}>
330	    <DeployView
331	      cat={{
332	        plans: planOptions,
333	        games: gameFamilies,
334	        hosting: hostingOptions,
335	        email: emailOptions,
336	        hostingMatrix,
337	        hostingTotalMatrix,
338	        hostingFirstMonthFreeCents,
339	        emailMatrix,
340	        emailTotalMatrix,
341	        oses: osOptions,
342	        terms: termOptions,
343	        addons: addonOptions,
344	        // Only regions where a Node actually exists — the wizard can never sell a
345	        // location we cannot provision in.
346	        regions: regionsFrom(nodes),
347	        diskPerGbCents,
348	        walletCents: user.balanceCents,
349	      }}
350	      priceMatrix={priceMatrix}
351	      hostingMatrix={hostingMatrix}
352	      emailMatrix={emailMatrix}
353	      firstName={user.name.split(" ")[0]}
354	      /* Which payment methods to OFFER. Read from the same predicates the
355	         charge paths use, so a method is never shown unless the platform can
356	         actually take money through it. In this sandbox all three are false by
357	         design, which is why the wallet is the only way to pay here. */
358	      methods={{
359	        card: stripeConfigured(),
360	        paypal: paypalConfigured(),
361	        crypto: coinbaseConfigured(),
362	      }}
363	      /* PayPal's PUBLIC client id. Safe to send to the browser — it is what the
364	         PayPal SDK script is keyed on and appears in every PayPal integration's
365	         page source. The SECRET stays on the server, where `createPayPalOrder`
366	         uses it. Null unless PayPal is actually configured, so the wizard can
367	         never mount the SDK against an empty id. */
368	      paypalClientId={paypalConfigured() ? process.env.PAYPAL_CLIENT_ID ?? null : null}
369	      isFirstTimeCustomer={isFirstTimeCustomer}
370	      exitIntentEnabled={exitIntentEnabled}
371	      fromCents={{
372	        // Same rule as every other "from $X" price on this page: lead with
373	        // the intro rate where one exists, not the post-grandfather-program
374	        // renewal rate — this tile is the first thing a new customer sees,
375	        // and it was still showing the higher number.
376	        vps: plans.length ? Math.min(...plans.map((p) => planIntroMonthlyCents(p) ?? p.priceCents)) : null,
377	        game: gamePlans.length ? Math.min(...gamePlans.map((g) => planIntroMonthlyCents(g) ?? g.priceCents)) : null,
378	        hosting: hostingPlans.length ? Math.min(...hostingPlans.map((h) => h.priceCents)) : null,
379	        email: emailPlans.length ? Math.min(...emailPlans.map((e) => e.priceCents)) : null,
380	        // No fixed plan row for domains — real price is a live per-TLD
381	        // registrar quote. 999 ($9.99) used to stand in here as a flat
382	        // guess; `null` renders this tile's existing "Pricing unavailable"
383	        // fallback instead of a number that isn't real.
384	        domains: null,
385	      }}
386	    />
387	    </Suspense>
388	  );
389	}
