1	"use client";
2	
3	import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
4	import { useSearchParams } from "next/navigation";
5	import { quoteOrder, type QuotedPrice } from "@/lib/nx/quote";
6	import { quoteGameOrder } from "@/lib/nx/quote-game";
7	import type { AddonOption, CartPrice, EmailPlanOption, GameFamilyOption, GameTier, HostingPlanOption, OsOption, PlanOption, TermOption } from "./order-types";
8	import type { Region } from "@/lib/nx/catalog";
9	import { DEPLOY_PARAM, type DeployIntent, type DeployService } from "@/lib/deploy-intent";
10	
11	/* Order state for the deploy wizard.
12	 *
13	 * Ported from the design sandbox with ONE structural change, and it is the
14	 * important one: the sandbox derived every money figure here in the browser
15	 * (`dueToday`, `saved`, `walletApplied`, `cardDue`) from a fixture price table.
16	 * None of that survives. The server is asked what the selection costs, and this
17	 * context only holds the answer. A price the browser works out is a second
18	 * pricing formula, and the first time it disagrees with `orderQuote` a customer
19	 * is shown one number and charged another.
20	 *
21	 * Kept exactly as designed:
22	 *  - Choosing a service seeds a COMPLETE, working configuration, so the order is
23	 *    buyable without touching anything. Only free defaults are pre-set; nothing
24	 *    that adds to the total is ever ticked for you.
25	 *  - Once a service is picked nothing is gated — you can commit from anywhere.
26	 *  - This is deliberately NOT a <form>. On the live platform an unkeyed ternary
27	 *    once made Continue and Deploy the same DOM node and charged five customers
28	 *    four steps early. The commit action is its own button and nothing else can
29	 *    submit.
30	 */
31	
32	export type ServiceKey = "vps" | "game" | "hosting" | "email" | "domains";
33	
34	export type Order = {
35	  service: ServiceKey | null;
36	  planId: string | null;
37	  termMonths: number;
38	  region: string | null;
39	  osId: string | null;
40	  hostname: string;
41	  addons: string[];
42	  diskGb: number;
43	  couponCode: string;
44	  useWallet: boolean;
45	  launched: boolean;
46	
47	  /* ── game ── */
48	  /** Family the customer picked; the tier below is what they actually buy. */
49	  gameFamily: string | null;
50	  gamePlanId: string | null;
51	  gameVariant: string | null;
