154	/**
155	 * The full seed for a freshly-chosen service — same defaults `chooseService`
156	 * has always set (a complete, immediately-priceable order with only free
157	 * defaults ticked), pulled out as a pure function so `orderFromIntent` below
158	 * can start from the identical baseline before layering a marketing button's
159	 * specific selections on top. Takes the PREVIOUS order as `base` only so
160	 * fields the picker doesn't own (nothing today) would survive a re-seed —
161	 * `chooseService` and `orderFromIntent` both currently pass a full record in.
162	 */
163	function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
164	  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
165	  return {
166	    ...base,
167	    service: k,
168	    planId: k === "vps" ? rec?.id ?? null : null,
169	    region: cat.regions[0]?.key ?? null,
170	    /* Must be a PLAIN_OS. Taking `oses[0]` picked whatever sorted first, and
171	       once the real catalogue landed that was Docker — an APPLICATION — so a
172	       fresh order defaulted to "operating system: Docker".
173	       Prefer the newest Ubuntu specifically — the most recognisable, most
174	       requested default — over whichever PLAIN_OS row happens to sort
175	       first alphabetically (AlmaLinux, before this). Falls back to the old
176	       "first PLAIN_OS" behavior if Ubuntu isn't in the catalogue at all. */
177	    osId: (
178	      cat.oses
179	        .filter((x) => x.category === "PLAIN_OS" && x.family === "ubuntu")
180	        .sort((a, b) => parseFloat(b.version || "0") - parseFloat(a.version || "0"))[0]
181	      ?? cat.oses.find((x) => x.category === "PLAIN_OS")
182	      ?? cat.oses[0]
183	    )?.id ?? null,
184	    termMonths: 1,
185	    hostname: k === "vps" ? "web-01" : "",
186	    serverName: k === "game" ? "My server" : "",
187	    addons: [],   // nothing that costs money is pre-selected
188	    diskGb: 0,
189	    /* A game order starts with NO family chosen — the picker is the next step,
190	       and pre-selecting one would put a product in the cart nobody asked for. */
191	    gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "",
192	    /* Hosting and email are bought against a DOMAIN, which only the customer
193	       can supply — there is no sensible default, so the field starts empty
194	       and the step is not "done" until they type one. */
195	    domain: "",
196	    subdomainLabel: "",
197	    /* Both seed their cheapest plan so the order is immediately priceable. */
198	    hostingPlanId: k === "hosting" ? (cat.hosting[0]?.id ?? null) : null,
199	    emailPlanId: k === "email" ? (cat.email[0]?.id ?? null) : null,
200	  };
201	}
