203	/** Reads a `DeployIntent` back off the URL, using the exact keys
204	 *  `lib/deploy-intent.ts`'s `deployHref` wrote — see that file for why each
205	 *  field has the query key it has. */
206	function parseIntent(sp: URLSearchParams): DeployIntent {
207	  const raw = (k: keyof DeployIntent) => sp.get(DEPLOY_PARAM[k]);
208	  const num = (k: keyof DeployIntent) => {
209	    const v = raw(k);
210	    if (!v) return undefined;
211	    const n = Number(v);
212	    return Number.isFinite(n) ? n : undefined;
213	  };
214	  const serviceRaw = raw("service");
215	  const service: DeployService | undefined =
216	    serviceRaw === "vps" || serviceRaw === "game" || serviceRaw === "hosting" || serviceRaw === "email"
217	      ? serviceRaw
218	      : undefined;
219	  const addonsRaw = raw("addons");
220	  return {
221	    service,
222	    planId: raw("planId") ?? undefined,
223	    termMonths: num("termMonths"),
224	    region: raw("region") ?? undefined,
225	    addons: addonsRaw ? addonsRaw.split(",").map((s) => s.trim()).filter(Boolean) : undefined,
226	    diskGb: num("diskGb"),
227	    gameFamily: raw("gameFamily") ?? undefined,
228	    gamePlanId: raw("gamePlanId") ?? undefined,
229	    gameVariant: raw("gameVariant") ?? undefined,
230	    players: num("players"),
231	    hostingPlanId: raw("hostingPlanId") ?? undefined,
232	    emailPlanId: raw("emailPlanId") ?? undefined,
233	    couponCode: raw("couponCode") ?? undefined,
234	  };
235	}
