237	/** The tier that best fits a desired headcount: the smallest slotted tier
238	 *  that still covers it, or — past the top of the ladder, or when the family
239	 *  has no slotted tiers at all — the single most expensive one, the closest
240	 *  real thing this family sells to "give me your biggest". Same judgment call
241	 *  GameLandingCombined's own player-count slider already makes, just applied
242	 *  against the LIVE catalogue instead of that page's illustrative fixture. */
243	function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
244	  if (tiers.length === 0) return null;
245	  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
246	  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
247	  if (fits) return fits.id;
248	  const pool = slotted.length ? slotted : tiers;
249	  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
250	}
