252	/**
253	 * Materializes a `DeployIntent` into a real, catalogue-validated `Order` —
254	 * every id is checked against `cat` before it's used, so a stale or tampered
255	 * query string (an old link to a plan that's since been deactivated, say)
256	 * degrades to `seedOrder`'s normal defaults for whatever field didn't match,
257	 * never to a broken or half-filled order. Returns null when the URL carries
258	 * no recognised `product`, so the wizard opens on its ordinary empty first
259	 * step exactly as it always has.
260	 */
261	function orderFromIntent(cat: Catalog, intent: DeployIntent): Order | null {
262	  if (!intent.service) {
263	    // No specific service in the URL — but a coupon may still be attached
264	    // (a promo CTA that deliberately lands on the plain service picker
265	    // rather than defaulting into one product, e.g. lib/actions-promo-trial.ts's
266	    // ANY-service trial coupon — "works on any Game Server or Cloud VPS
267	    // plan" stops being true in practice if the button always drops the
268	    // customer into Game Servers specifically). Carry the coupon into the
269	    // ordinary empty first step instead of dropping it entirely.
270	    return intent.couponCode ? { ...EMPTY, couponCode: intent.couponCode } : null;
271	  }
272	  const o = seedOrder(EMPTY, cat, intent.service);
273	  // Applied regardless of which service branch runs below — a coupon covering
274	  // "any VPS or Game Server" (see lib/promo-trial.ts) isn't service-specific,
275	  // it just needs a real order to attach to.
276	  if (intent.couponCode) o.couponCode = intent.couponCode;
277	
278	  const term = intent.termMonths;
279	  if (term != null && cat.terms.some((t) => t.months === term)) o.termMonths = term;
280	
281	  if (intent.service === "vps") {
282	    if (intent.planId && cat.plans.some((p) => p.id === intent.planId)) o.planId = intent.planId;
283	    if (intent.region && cat.regions.some((r) => r.key === intent.region)) o.region = intent.region;
284	    if (intent.addons?.length) {
285	      const valid = new Set<string>(cat.addons.map((a) => a.key));
286	      const picked = intent.addons.filter((a) => valid.has(a));
287	      if (picked.length) o.addons = picked;
288	    }
289	    if (intent.diskGb != null && intent.diskGb >= 0) o.diskGb = Math.round(intent.diskGb);
290	  }
291	
292	  if (intent.service === "game") {
293	    const g = intent.gameFamily ? cat.games.find((x) => x.family === intent.gameFamily) : null;
294	    if (g) {
295	      o.gameFamily = g.family;
296	      const exact = intent.gamePlanId ? g.tiers.find((t) => t.id === intent.gamePlanId) : null;
297	      o.gamePlanId =
298	        exact?.id
299	        ?? (intent.players && intent.players > 0 ? nearestTierBySlots(g.tiers, intent.players) : null)
300	        ?? [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0]?.id
301	        ?? null;
302	      o.gameVariant =
303	        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
304	          ? intent.gameVariant
305	          : g.defaultVariant;
306	    }
307	  }
308	
309	  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
310	    o.hostingPlanId = intent.hostingPlanId;
311	  }
312	
313	  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
314	    o.emailPlanId = intent.emailPlanId;
315	  }
316	
317	  return o;
318	}
