323	export function OrderProvider({ cat, children }: { cat: Catalog; children: React.ReactNode }) {
324	  // Read once, on mount: a marketing "Deploy" button's selection, carried here
325	  // via `/dashboard/deploy?product=...` (see lib/deploy-intent.ts) — including
326	  // unchanged across a login/signup detour, since that's just the existing
327	  // `?next=` convention carrying this same query string through (see
328	  // lib/safe-next.ts, app/login/page.tsx, app/dashboard/layout.tsx).
329	  // `useSearchParams()` needs this component under a Suspense boundary, which
330	  // app/dashboard/deploy/page.tsx provides around <DeployView>.
331	  const searchParams = useSearchParams();
332	  const [o, setO] = useState<Order>(() => orderFromIntent(cat, parseIntent(searchParams)) ?? EMPTY);
333	  const [price, setPrice] = useState<CartPrice>(null);
334	  const [pricing, setPricing] = useState(false);
335	  const [priceError, setPriceError] = useState<string | null>(null);
336	
337	  const set = useCallback(<K extends keyof Order>(k: K, v: Order[K]) => {
338	    setO((p) => ({ ...p, [k]: v }));
339	  }, []);
340	
341	  const chooseService = useCallback((k: ServiceKey) => {
342	    setO((p) => seedOrder(p, cat, k));
343	  }, [cat]);
344	
345	  /* Choosing a family seeds its cheapest tier and its default loader, so the
346	     order is immediately priceable; the customer changes what they care about. */
347	  const chooseGame = useCallback((family: string) => {
348	    const g = cat.games.find((x) => x.family === family);
349	    if (!g) return;
350	    const cheapest = [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0];
351	    setO((p) => ({
352	      ...p,
353	      gameFamily: family,
354	      gamePlanId: cheapest?.id ?? null,
355	      gameVariant: g.defaultVariant,
356	      subdomain: "",
357	      // A previous game's field values (e.g. Valheim's SERVER_PASS) must never
358	      // leak into a different family's config — keys rarely collide, but when
359	      // they do (two families both using SERVER_PASS) a stale value would
360	      // silently carry over instead of the customer setting their own.
361	      gameConfig: {},
362	    }));
363	  }, [cat]);
364	
365	  const toggleAddon = useCallback((k: string) => {
366	    setO((p) => ({
367	      ...p,
368	      addons: p.addons.includes(k) ? p.addons.filter((x) => x !== k) : [...p.addons, k],
369	    }));
370	  }, []);
371	
372	  const plan = useMemo(() => cat.plans.find((p) => p.id === o.planId) ?? null, [cat.plans, o.planId]);
373	  const game = useMemo(
374	    () => cat.games.find((g) => g.family === o.gameFamily) ?? null,
375	    [cat.games, o.gameFamily]
376	  );
377	
378	  /* ── live pricing ────────────────────────────────────────────────────────
379	     Debounced, and guarded against out-of-order replies: dragging the disk
380	     slider fires many quotes and they can come back in any order, so a stale
381	     one must never overwrite a newer one. Without the sequence check the cart
382	     can settle on the price of a selection the customer already moved past. */
383	  const seq = useRef(0);
384	  useEffect(() => {
385	    /* One effect, two products. Each asks ITS OWN server-side quote — the VPS
386	       one through `orderQuote`, the game one through `gameOrderQuote` — because
387	       the two price completely differently (a game tier is a flat term price;
388	       a VPS accrues add-ons, disk and a dedicated IP). Nothing here does
389	       arithmetic; it only chooses which server function to ask. */
390	    const vpsReady = o.service === "vps" && o.planId && o.osId;
391	    /* Minecraft cannot be quoted without its play subdomain: `quoteGameOrder`
392	       claims-checks the name, so asking before the customer has typed one comes
393	       back an error, and the wizard rendered that as a bare "—" total with the
394	       explanation buried in the cart. Wait for the field the family actually
395	       requires, and let the bar say what is missing instead. */
396	    const gameNeedsSubdomain = o.service === "game" && !!game?.needsSubdomain;
397	    const gameReady = o.service === "game" && o.gamePlanId
398	      && (!gameNeedsSubdomain || o.subdomain.trim().length > 2);
399	
400	    /* Hosting and email price from the server-built matrix the page handed down
401	       (termPriceCents — the same helper their charge paths use), so there is no
402	       round-trip to make and nothing for this effect to await. Still not derived
403	       HERE: the browser looks a value up, it does not compute one. */
404	    /* A domain is priced per YEAR by the registrar, already carrying our markup
405	       — there is no plan and no term ladder. The number came back from
406	       `searchDomains`; multiplying it by the years is the one arithmetic this
407	       file does, and it is the same multiplication `purchaseDomain` performs. */
408	    if (o.service === "domains") {
409	      if (o.domainPriceCents === null) { setPrice(null); setPriceError(null); return; }
410	      const total = o.domainPriceCents * o.years;
411	      setPricing(false);
412	      setPriceError(null);
413	      setPrice({
414	        totalCents: total, months: o.years * 12, regularPlanCents: total,
415	        promoName: "", promoCreditCents: 0,
416	        couponLabel: null, couponDiscountCents: 0, couponError: null,
417	        introRenewalMonthly: null,
418	        renewalTotalCents: total,
419	      });
420	      return;
421	    }
422	
423	    // Read the real term total directly — NOT the *Matrix per-month rate
424	    // multiplied back up. That rate is already rounded once (for its own
425	    // "$X/mo" display), so re-multiplying it by the term double-rounds and
426	    // drifts a cent or two from what the charge path actually bills (see
427	    // hostingTotalMatrix's comment in Catalog above).
428	    const total =
429	      o.service === "hosting" ? cat.hostingTotalMatrix[o.hostingPlanId ?? ""]?.[o.termMonths]
430	      : o.service === "email" ? cat.emailTotalMatrix[o.emailPlanId ?? ""]?.[o.termMonths]
431	      : undefined;
432	    if (total !== undefined) {
433	      // Hosting only, and only for a customer who still actually qualifies
434	      // (lib/promo-redemption.ts, resolved server-side per-request) — the
435	      // credit is 0 for email, and 0 for hosting once already claimed on
436	      // this account/IP, so `total` (the full price) is what shows either way.
437	      const promoCreditCents =
438	        o.service === "hosting" ? Math.min(total, cat.hostingFirstMonthFreeCents[o.hostingPlanId ?? ""] ?? 0) : 0;
439	      setPricing(false);
440	      setPriceError(null);
441	      setPrice({
442	        totalCents: total - promoCreditCents,
443	        months: o.termMonths,
444	        // The full, undiscounted term total — what the struck-through "was"
445	        // price (if the wizard shows one) should read, matching how the VPS
446	        // quote already reports `regularPlanCents` alongside its discounted total.
447	        regularPlanCents: total,
448	        promoName: promoCreditCents > 0 ? "First month free" : "",
449	        promoCreditCents,
450	        couponLabel: null, couponDiscountCents: 0, couponError: null,
451	        introRenewalMonthly: null,
452	        // The full undiscounted term total — first-month-free is a one-time
453	        // credit, never repeated at renewal, same reasoning as regularPlanCents.
454	        renewalTotalCents: total,
455	      });
456	      return;
457	    }
458	
459	    if (!vpsReady && !gameReady) { setPrice(null); setPriceError(null); return; }
460	
461	    const mine = ++seq.current;
462	    setPricing(true);
463	    const t = setTimeout(async () => {
464	      if (gameReady) {
465	        const res = await quoteGameOrder({
466	          gamePlanId: o.gamePlanId!,
467	          termMonths: o.termMonths,
468	          serverName: o.serverName.trim() || undefined,
469	          variant: o.gameVariant ?? undefined,
470	          subdomain: o.subdomain.trim() || undefined,
471	          config: o.gameConfig,
472	          couponCode: o.couponCode.trim().toUpperCase() || undefined,
473	        });
474	        if (mine !== seq.current) return;
475	        setPricing(false);
476	        if (!res.ok) { setPrice(null); setPriceError(res.error); return; }
477	        setPriceError(null);
478	        setPrice({
479	          // chargeCents is already net of couponDiscountCents (gameOrderQuote,
480	          // lib/game-order.ts) — the same number payAndDeployGame charges.
481	          totalCents: res.chargeCents,
482	          months: res.months,
483	          /* No coupon: chargeCents IS the regular price, nothing to strike
484	             through. With one: adding the discount back gives the real
485	             pre-coupon total ("was $X") — algebra on the two authoritative
486	             numbers the quote already returned, not a second price formula
487	             (chargeCents = the pre-coupon total - couponDiscountCents, per
488	             gameOrderQuote). */
489	          regularPlanCents: res.chargeCents + res.couponDiscountCents,
490	          promoName: "",
491	          promoCreditCents: 0,
492	          couponLabel: res.couponLabel,
493	          couponDiscountCents: res.couponDiscountCents,
494	          couponError: res.couponError,
495	          // `res.monthlyCents` is the tier's RAW regular per-month rate — the
496	          // exact same basis lib/renewal-charge.ts renews a game server at —
497	          // so this is only ever populated alongside a genuine intro price
498	          // (introPercent > 0), never the regular price restated as a warning.
499	          introRenewalMonthly: res.introPercent > 0 ? res.monthlyCents : null,
500	          // Flat all-in price — no separate recurring add-ons exist for a game
501	          // plan (lib/renewal-charge.ts's isGame branch), so chargeCents IS
502	          // the true renewal amount.
503	          renewalTotalCents: res.chargeCents,
504	        });
505	        return;
506	      }
507	
508	      const res = await quoteOrder({
509	        planId: o.planId!,
510	        osTemplateId: o.osId!,
511	        hostname: o.hostname.trim() || "web-01",
512	        termMonths: o.termMonths,
513	        addonBackup: o.addons.includes("backup"),
514	        /* `orderQuote` (lib/order.ts) prices backup off `backupTier`
