export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export async function generateMetadata(): Promise<Metadata> {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const pricing = cheapestVpsPricing(plans);
  const from = pricing?.fromLabel ?? "$6.49";

  return {
    title: "Free VPS Trial — Start Free, No Credit Card Required",
    description:
      `Start free with no credit card, and claim any free-credit or free-VPS promo in your dashboard when available. Paid servers you keep start at ${from}/mo, all-in.`,
    alternates: { canonical: "/free-vps" },
    openGraph: {
      type: "article",
      title: "Free VPS Trial — Start Free, No Credit Card Required",
      description:
        `Sign up free with no card and claim any free-credit offer in your dashboard. Honest pricing: servers you keep are billed monthly from ${from}.`,
      url: `${APP_URL}/free-vps`,
    },
  };
}

function buildContent(pricing: ReturnType<typeof cheapestVpsPricing>): UseCaseContent {
  const planName = pricing?.planName ?? "Nano";
