/** The whole campaign's real, shared deadline — 7 days from launch, UTC. */
export const CAMPAIGN_END = new Date("2026-09-29T00:00:00.000Z");

/** Per-visitor window from first sight of the popup. See the doc comment above. */
export const PERSONAL_WINDOW_MINUTES = 96;

export function personalWindowMs(): number {
  return PERSONAL_WINDOW_MINUTES * 60_000;
}

/**
 * Whether the trial campaign is currently running. Used to hide the
 * evergreen shared-hosting PromoBar for the duration — a customer landing
 * on one $-off strip and then getting a second, different one immediately
 * below it (marketing's own call, 2026-09-22: mute the evergreen one while
 * this one runs rather than stack them) reads as noise, not two offers.
 */
export function isTrialCampaignActive(): boolean {
  return new Date() < CAMPAIGN_END;
}
