import { chromium } from "playwright";

const BASE = "http://127.0.0.1:8080";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad";

const browser = await chromium.launch();

async function shotSection(url, selector, name, viewport = { width: 1440, height: 1400 }) {
  const ctx = await browser.newContext({ viewport });
  const page = await ctx.newPage();
  await page.goto(BASE + url, { waitUntil: "networkidle", timeout: 60000 });
  // dismiss cookie banner if present
  const gotIt = page.getByText("Got it", { exact: true });
  if (await gotIt.count()) await gotIt.first().click().catch(() => {});
  await page.waitForTimeout(300);
  const el = page.locator(selector).first();
  await el.scrollIntoViewIfNeeded();
  await page.waitForTimeout(500);
  await el.screenshot({ path: `${OUT}/${name}.png` });
  await ctx.close();
  console.log("saved", name);
}

