import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import fs from "node:fs";

const BASE = "https://nxeon.cloud";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/mkt/shots";
fs.mkdirSync(OUT, { recursive: true });

const PAGES = (process.argv[2] ?? "/,/pricing,/game-servers,/minecraft-server-hosting,/valheim-server-hosting,/free-minecraft,/free-vps,/vps,/web-hosting,/login,/register,/domains,/contact,/tools/latency-test").split(",");
const VIEWPORTS = (process.argv[3] ?? "mobile,desktop").split(",");
const VP = {
  mobile: { viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2,
            userAgent: "Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1" },
  desktop: { viewport: { width: 1440, height: 900 } },
};
const BLOCK_HOSTS = /facebook\.(net|com)|google-analytics|googletagmanager|doubleclick|googleadservices|clarity\.ms|hotjar/;

const browser = await chromium.launch();
const results = [];
for (const vpName of VIEWPORTS) {
  for (const path of PAGES) {
    const ctx = await browser.newContext({ ...VP[vpName] });
    await ctx.route("**/*", (r) => {
      const req = r.request();
      if (req.method() !== "GET") return r.abort();
      if (BLOCK_HOSTS.test(req.url())) return r.abort();
      return r.continue();
    });
    const page = await ctx.newPage();
    const errors = [];
    const failed = [];
    page.on("console", (m) => { if (m.type() === "error") errors.push(m.text().slice(0, 300)); });
    page.on("pageerror", (e) => errors.push("PAGEERROR: " + String(e.message).slice(0, 300)));
    page.on("response", (res) => {
      const u = res.url();
      if (res.status() >= 400 && u.startsWith(BASE)) failed.push(`${res.status()} ${u.replace(BASE, "")}`);
    });
    const t0 = Date.now();
    let status = 0;
    try {
      const resp = await page.goto(BASE + path, { waitUntil: "load", timeout: 60000 });
      status = resp?.status() ?? 0;
    } catch (e) { errors.push("GOTO: " + e.message.slice(0, 200)); }
    const loadMs = Date.now() - t0;
    await page.waitForTimeout(2500);
    // scroll through the page to trigger lazy/reveal content
    await page.evaluate(async () => {
      const h = document.scrollingElement.scrollHeight;
      for (let y = 0; y < h; y += 700) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 60)); }
      window.scrollTo(0, 0);
    });
    await page.waitForTimeout(800);

    const m = await page.evaluate(() => {
      const vw = window.innerWidth;
      const se = document.scrollingElement;
      const out = { vw, scrollWidth: se.scrollWidth, bodyScrollWidth: document.body.scrollWidth, scrollHeight: se.scrollHeight };
      const clips = (el) => {
        for (let a = el.parentElement; a && a !== document.body; a = a.parentElement) {
          const cs = getComputedStyle(a);
          if (["auto", "scroll", "hidden", "clip"].includes(cs.overflowX)) {
            const r = a.getBoundingClientRect();
            if (r.right <= vw + 1) return true;
          }
        }
        return false;
      };
      const desc = (el) => {
        const cls = (el.getAttribute("class") || "").replace(/\s+/g, " ").slice(0, 140);
        const id = el.id ? "#" + el.id : "";
        const txt = (el.innerText || "").trim().replace(/\s+/g, " ").slice(0, 50);
        return `${el.tagName.toLowerCase()}${id} [${cls}] "${txt}"`;
      };
      const offenders = [];
      for (const el of document.body.querySelectorAll("*")) {
        const r = el.getBoundingClientRect();
        if (r.width === 0 || r.height === 0) continue;
        const cs = getComputedStyle(el);
        if (cs.position === "fixed") continue;
        if (r.right > vw + 1 || r.left < -1) {
          if (clips(el)) continue;
          // only keep "leaf-most" offenders: skip if a child also offends
          let childOff = false;
          for (const c of el.children) {
            const cr = c.getBoundingClientRect();
            if (cr.width && (cr.right > vw + 1 || cr.left < -1)) { childOff = true; break; }
          }
          if (!childOff) offenders.push({ d: desc(el), left: Math.round(r.left), right: Math.round(r.right), w: Math.round(r.width) });
        }
      }
      out.offenders = offenders.slice(0, 15);
      out.offenderCount = offenders.length;
      // fixed/sticky elements visible in viewport (overlays)
      const fixed = [];
      for (const el of document.body.querySelectorAll("*")) {
        const cs = getComputedStyle(el);
        if ((cs.position === "fixed" || cs.position === "sticky") && cs.display !== "none" && cs.visibility !== "hidden" && +cs.opacity > 0.05) {
          const r = el.getBoundingClientRect();
          if (r.width > 40 && r.height > 20 && r.bottom > 0 && r.top < window.innerHeight) {
            fixed.push({ d: desc(el).slice(0, 170), pos: cs.position, top: Math.round(r.top), h: Math.round(r.height), w: Math.round(r.width), z: cs.zIndex });
          }
        }
      }
      out.fixed = fixed.slice(0, 12);
      // small tap targets among links/buttons in viewport-wide page
      let small = 0; const smallEx = [];
      for (const el of document.querySelectorAll("a[href], button, [role=button], input, select, summary")) {
        const r = el.getBoundingClientRect();
        if (!r.width || !r.height) continue;
        const cs = getComputedStyle(el);
        if (cs.visibility === "hidden" || cs.display === "none") continue;
        if (r.height < 32 || r.width < 32) {
          // inline text links inside paragraphs are fine
          if (el.tagName === "A" && el.closest("p, li") && cs.display === "inline") continue;
          small++; if (smallEx.length < 6) smallEx.push(`${desc(el).slice(0, 90)} ${Math.round(r.width)}x${Math.round(r.height)}`);
        }
      }
      out.smallTargets = small; out.smallEx = smallEx;
      // text too small
      let tiny = 0;
      for (const el of document.body.querySelectorAll("p, span, li, a, td, small")) {
        if (!el.childNodes.length || ![...el.childNodes].some((n) => n.nodeType === 3 && n.textContent.trim().length > 3)) continue;
        const fs = parseFloat(getComputedStyle(el).fontSize);
        const r = el.getBoundingClientRect();
        if (r.width && fs < 11) tiny++;
      }
      out.tinyText = tiny;
      out.htmlBytes = document.documentElement.outerHTML.length;
      return out;
    });
    await page.screenshot({ path: `${OUT}/${vpName}${path.replace(/\//g, "_") || "_home"}.png`, fullPage: false });
    results.push({ vp: vpName, path, status, loadMs, errors: [...new Set(errors)].slice(0, 8), failed: [...new Set(failed)].slice(0, 8), ...m });
    console.log(JSON.stringify(results.at(-1)));
    await ctx.close();
  }
}
fs.writeFileSync(`${OUT}/../mobile-results.json`, JSON.stringify(results, null, 1));
await browser.close();

