/**
 * "Global network" band (v7/v8) — a real DOTTED WORLD MAP (continents rendered as
 * dot clusters from continent footprints) with labelled PoP nodes on true-ish
 * geography, linked by brand-gradient arcs with travelling data pulses. Framed in
 * a console panel so it reads as a deliberate visualization, not floating dots.
 * Pure SVG + scoped CSS, deterministic (SSR-safe), no assets.
 */
const W = 1000, H = 460;
// continent footprints (equirectangular-ish ellipses on the viewBox)
const LAND = [
  { cx: 205, cy: 150, rx: 120, ry: 92 },  // North America
  { cx: 300, cy: 335, rx: 52, ry: 92 },   // South America
  { cx: 355, cy: 70, rx: 42, ry: 34 },    // Greenland
  { cx: 520, cy: 128, rx: 55, ry: 52 },   // Europe
  { cx: 548, cy: 275, rx: 72, ry: 100 },  // Africa
  { cx: 730, cy: 150, rx: 168, ry: 98 },  // Asia
  { cx: 800, cy: 300, rx: 40, ry: 34 },   // SE Asia / Indonesia
  { cx: 878, cy: 352, rx: 58, ry: 40 },   // Australia
];
const noise = (i: number, j: number) => { const s = Math.sin(i * 12.9898 + j * 78.233) * 43758.5453; return s - Math.floor(s); };
function landDots() {
  const dots: { x: number; y: number; o: number }[] = [];
  const step = 13;
  for (let x = step; x < W; x += step) {
    for (let y = 30; y < H - 20; y += step) {
      let best = 2;
      for (const c of LAND) { const t = ((x - c.cx) / c.rx) ** 2 + ((y - c.cy) / c.ry) ** 2; if (t < best) best = t; }
      const n = noise(x, y);
      if (best < 0.88 || (best < 1 && n > 0.55)) dots.push({ x: x + (n - 0.5) * 4, y: y + (noise(y, x) - 0.5) * 4, o: 0.22 + (1 - best) * 0.3 });
    }
  }
  return dots;
}
const CITIES = [
  { name: "Toronto", x: 232, y: 150 }, { name: "New York", x: 258, y: 176 },
  { name: "Amsterdam", x: 520, y: 116 }, { name: "Frankfurt", x: 545, y: 132 },
  { name: "Singapore", x: 790, y: 300 }, { name: "Tokyo", x: 848, y: 158 },
  { name: "Sydney", x: 888, y: 350 },
];
const LINKS: [number, number][] = [[1, 2], [0, 1], [3, 4], [2, 3], [4, 5], [4, 6], [5, 6], [1, 3]];
const arcPath = (a: { x: number; y: number }, b: { x: number; y: number }) => {
  const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2 - Math.hypot(a.x - b.x, a.y - b.y) * 0.26;
  return `M${a.x},${a.y} Q${mx},${my} ${b.x},${b.y}`;
};
export function NetworkMap() {
  const dots = landDots();
  return (
    <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-950/60 glow-brand">
      <style>{`
        @keyframes nm-pulse { 0%{offset-distance:0%;opacity:0} 12%{opacity:1} 88%{opacity:1} 100%{offset-distance:100%;opacity:0} }
        @keyframes nm-blip { 0%,100%{opacity:.5} 50%{opacity:1} }
        @media (prefers-reduced-motion: reduce){ .nm-pulse{animation:none!important;opacity:0} }
      `}</style>
      {/* header */}
      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5 font-mono text-[11px]">
        <span className="flex items-center gap-2 text-slate-500"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /> nxeon · global network</span>

