/**
 * A "live" integer that idles around a base value with small jitter, evoking a
 * ticking player count / TPS readout. Static (base) under reduced motion.
 */
export function useJitter(base: number, swing: number, active: boolean, ms = 2600, reduced = false) {
  const [val, setVal] = useState(base);
  useEffect(() => {
    if (!active || reduced) {
      setVal(base);
      return;
    }
    const id = window.setInterval(() => {
      if (document.hidden) return;
      const delta = Math.round((Math.random() - 0.45) * swing);
      setVal((v) => Math.max(base - swing, Math.min(base + swing, v + delta)));
    }, ms);
    return () => window.clearInterval(id);
  }, [base, swing, active, ms, reduced]);
  return val;
}

